// Photos are compressed and stored with the existing local records and backups.
let monthCursor=new Date(new Date().getFullYear(),new Date().getMonth(),1),photoDraft='',photoOriginal='',photoBusy=false,photoGeneration=0;
const photoSrc=r=>r.photo||'cup.svg';
function renderMonth(){
 const y=monthCursor.getFullYear(),m=monthCursor.getMonth(),prefix=`${y}-${String(m+1).padStart(2,'0')}`,monthItems=records.filter(r=>r.date.startsWith(prefix));
 $('#month-title').textContent=monthCursor.toLocaleString('en-US',{month:'long'});$('#month-year').textContent=`${y} · 奶茶贴纸簿`;
 const blanks=(monthCursor.getDay()+6)%7,days=new Date(y,m+1,0).getDate();
 $('#month-grid').innerHTML='<span class="month-weekday">一</span><span class="month-weekday">二</span><span class="month-weekday">三</span><span class="month-weekday">四</span><span class="month-weekday">五</span><span class="month-weekday">六</span><span class="month-weekday">日</span>'+Array.from({length:blanks},()=>'<span></span>').join('')+Array.from({length:days},(_,i)=>{const date=`${prefix}-${String(i+1).padStart(2,'0')}`,cups=monthItems.filter(r=>r.date===date);return `<button class="month-day ${cups.length?'with-sticker':''} ${date===dateKey(new Date())?'is-today':''} ${selected===date?'picked':''}" data-month-date="${date}" aria-label="${m+1}月${i+1}日，${cups.length}杯"><span class="month-number">${i+1}</span>${cups.length?`<img class="drink-sticker" src="${photoSrc(cups[cups.length-1])}" alt="">${cups.length>1?`<span class="cup-count">${cups.length}</span>`:''}`:''}</button>`}).join('');
 const brands=[...new Set(monthItems.map(r=>r.brand.trim()).filter(Boolean))],freq={};monthItems.forEach(r=>{const k=r.name||r.category;freq[k]=(freq[k]||0)+1});const fav=Object.entries(freq).sort((a,b)=>b[1]-a[1])[0];
 $('#month-total').textContent=`${monthItems.length} 杯`;$('#month-shops').textContent=`${brands.length} 家店 · 喝过就留下贴纸`;
 $('#month-fav').textContent=fav?fav[0]:'本月 C 位待定';$('#month-fav-note').textContent=fav?`这个月选了它 ${fav[1]} 次`:'第一杯选手，请入场。';
 $('#month-collection').innerHTML=monthItems.slice(-5).map(r=>`<img class="drink-sticker" src="${photoSrc(r)}" alt="${esc(r.name||r.category)}">`).join('')||'<img src="cup.svg" alt="" class="collection-empty">';
 $('#month-day-detail').hidden=!selected||!selected.startsWith(prefix);
 if(selected&&selected.startsWith(prefix)){const cups=records.filter(r=>r.date===selected);$('#month-day-title').textContent=`${parseDate(selected).getMonth()+1} 月 ${parseDate(selected).getDate()} 日 · ${cups.length} 杯`;$('#month-day-cups').innerHTML=cups.map(r=>`<button data-edit-cup="${esc(r.id)}"><img class="drink-sticker" src="${photoSrc(r)}" alt=""><span>${esc(r.name||r.category)}</span><small>${esc(r.brand||'未填写品牌')}</small></button>`).join('')||'<p>这一天还没有奶茶，来贴第一杯？</p>'}
}
const originalRender=render;
render=function(){originalRender();document.querySelectorAll('#records [data-id]').forEach(el=>{const r=records.find(r=>r.id===el.dataset.id);if(r?.photo){el.querySelector('img').src=r.photo;el.querySelector('img').classList.add('drink-sticker')}});renderMonth()};
const originalOpenForm=openForm;
openForm=function(id){photoGeneration++;photoBusy=false;originalOpenForm(id);photoDraft=records.find(r=>r.id===id)?.photo||'';photoOriginal=photoDraft;$('#photo-file').value='';updatePhotoPreview()};
function updatePhotoPreview(){const has=!!photoDraft;$('#photo-preview').src=photoDraft||'cup.svg';$('#photo-preview').classList.toggle('has-photo',has);$('#photo-remove').disabled=!has||photoBusy;$('#photo-cutout').disabled=!has||photoBusy;$('#photo-restore').disabled=!has||photoBusy;$('#photo-file').disabled=photoBusy;$('#form button[type=submit]').disabled=photoBusy;$('#photo-status').textContent=photoBusy?'正在制作贴纸…':has?'贴纸准备好了，保存后贴进日历。':'拍一杯、选一张，把它贴进日历。'}
function imageFrom(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=src})}
function canvasFor(img,max=360){const c=document.createElement('canvas'),ratio=Math.min(1,max/Math.max(img.width,img.height));c.width=Math.max(1,Math.round(img.width*ratio));c.height=Math.max(1,Math.round(img.height*ratio));c.getContext('2d').drawImage(img,0,0,c.width,c.height);return c}
function encodeSticker(c){return c.toDataURL('image/webp',.78)}
$('#photo-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;const generation=++photoGeneration;photoBusy=true;updatePhotoPreview();let url;try{if(file.size>20*1024*1024)throw Error();url=URL.createObjectURL(file);const img=await imageFrom(url);if(generation!==photoGeneration)return;photoDraft=encodeSticker(canvasFor(img));photoOriginal=photoDraft}catch{toast('这张照片暂时无法读取，请选择 20MB 以内的 JPG、PNG 或 WebP 图片。')}finally{if(url)URL.revokeObjectURL(url);if(generation===photoGeneration){photoBusy=false;updatePhotoPreview()}}};
$('#photo-remove').onclick=()=>{photoDraft='';photoOriginal='';updatePhotoPreview()};$('#photo-restore').onclick=()=>{photoDraft=photoOriginal;updatePhotoPreview()};
$('#photo-cutout').onclick=async()=>{if(!photoOriginal)return;const generation=++photoGeneration;photoBusy=true;updatePhotoPreview();try{const c=canvasFor(await imageFrom(photoOriginal)),ctx=c.getContext('2d'),im=ctx.getImageData(0,0,c.width,c.height),d=im.data,w=c.width,h=c.height,seen=new Uint8Array(w*h),queue=new Int32Array(w*h);let head=0,tail=0;const corners=[0,w-1,(h-1)*w,w*h-1].map(i=>[d[i*4],d[i*4+1],d[i*4+2]]);const matches=i=>d[i*4+3]<25||corners.some(rgb=>Math.hypot(d[i*4]-rgb[0],d[i*4+1]-rgb[1],d[i*4+2]-rgb[2])<48);const add=i=>{if(i<0||i>=w*h||seen[i])return;seen[i]=1;if(matches(i))queue[tail++]=i};for(let x=0;x<w;x++){add(x);add((h-1)*w+x)}for(let y=0;y<h;y++){add(y*w);add(y*w+w-1)}while(head<tail){const i=queue[head++];d[i*4+3]=0;if(i%w)add(i-1);if(i%w<w-1)add(i+1);add(i-w);add(i+w)}ctx.putImageData(im,0,0);let left=w,top=h,right=0,bottom=0;for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(d[(y*w+x)*4+3]>25){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y)}if(right<=left||bottom<=top)throw Error();const cropped=document.createElement('canvas');cropped.width=right-left+17;cropped.height=bottom-top+17;cropped.getContext('2d').drawImage(c,left,top,right-left+1,bottom-top+1,8,8,right-left+1,bottom-top+1);if(generation===photoGeneration){photoDraft=encodeSticker(cropped);toast('背景已处理；不满意可以点「恢复原图」。')}}catch{toast('没有识别出清晰的杯子边界，请换纯色背景照片或直接上传透明贴纸。')}finally{if(generation===photoGeneration){photoBusy=false;updatePhotoPreview()}}};
$('#month-prev').onclick=()=>{monthCursor=new Date(monthCursor.getFullYear(),monthCursor.getMonth()-1,1);selected=null;renderMonth()};$('#month-next').onclick=()=>{monthCursor=new Date(monthCursor.getFullYear(),monthCursor.getMonth()+1,1);selected=null;renderMonth()};$('#month-current').onclick=()=>{monthCursor=new Date(new Date().getFullYear(),new Date().getMonth(),1);selected=null;renderMonth()};
$('#month-grid').onclick=e=>{const button=e.target.closest('[data-month-date]');if(!button)return;selected=button.dataset.monthDate;week=monday(parseDate(selected));render();};$('#month-day-cups').onclick=e=>{const b=e.target.closest('[data-edit-cup]');if(b)openForm(b.dataset.editCup)};$('#month-add').onclick=()=>openForm();render();
